#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, h;
    cin >> n >> h;

    // Initialize a 2D vector for dynamic programming with -1
    vector<vector<long long>> dp_array(n + 1, vector<long long>(n + 1, -1));
    dp_array[0][0] = 1;

    function<long long(int, int)> count_trees = [&](int n, int h) -> long long {
        if (dp_array[n][h] != -1) {
            return dp_array[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return count_trees(n, 1);
        }

        long long total_count = 0;
        for (int i = 0; i < n; ++i) {
            total_count += count_trees(n - i - 1, 0) * count_trees(i, h - 1);
            total_count += count_trees(n - i - 1, h - 1) * count_trees(i, 0);
            total_count -= count_trees(n - i - 1, h - 1) * count_trees(i, h - 1);
        }

        dp_array[n][h] = total_count;
        return total_count;
    };

    cout << count_trees(n, h) << endl;
    return 0;
}
